public static IServiceCollection AddQuartzHostedService(
    this IServiceCollection services,
    Action<QuartzHostedServiceOptions>? configure = null)
{
    return services.AddQuartzHostedService<QuartzHostedService>(configure);
}

public static IServiceCollection AddQuartzHostedService<[DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicConstructors)] T>(
    this IServiceCollection services,
    Action<QuartzHostedServiceOptions>? configure = null)
    where T : QuartzHostedService
{
    ArgumentNullException.ThrowIfNull(services);

    if (configure is not null)
    {
        // Every scheduler's options, not only the default scheduler's: one hosted service used to
        // read one options object for all of them, and a setting like WaitForJobsToComplete has to
        // go on meaning what it did.
        services.ConfigureAll(configure);
    }

    // Registered whatever else the container holds. The service resolves its schedulers when the host
    // starts, so this no longer has to be called after AddQuartz to have any effect — and a container
    // with no scheduler in it is reported at startup rather than silently doing nothing.
    AddHostedService(services, typeof(T));

    return services;

public static IServiceCollection AddQuartzHostedService(
    this IServiceCollection services,
    string schedulerName,
    Action<QuartzHostedServiceOptions>? configure = null)
{
    ArgumentNullException.ThrowIfNull(services);
    ArgumentException.ThrowIfNullOrWhiteSpace(schedulerName);

    if (configure is not null)
    {
        // PostConfigure rather than Configure, so this scheduler's own settings are applied after the
        // shared ones no matter which call came first.
        services.PostConfigure(schedulerName, configure);
    }

    // So that configuring one scheduler is enough to have the schedulers started, without a second
    // hosted service appearing when the application also called AddQuartzHostedService().
    AddHostedService(services, typeof(QuartzHostedService));

    return services;

public sealed class QuartzHostedServiceOptions
{
    /// <summary>
    /// If <see langword="true" /> the scheduler will not allow shutdown process
    /// to return until all currently executing jobs have completed.
    /// </summary>
    public bool WaitForJobsToComplete { get; set; }

    /// <summary>
    /// <para>
    /// If not <see langword="null" /> the scheduler will start after specified delay.
    /// </para>
    /// <para>
    /// If <see cref="AwaitApplicationStarted"/> is true, the delay starts when application startup completes.
    /// </para>
    /// </summary>
    public TimeSpan? StartDelay { get; set; }

    /// <summary>
    /// If true (default), jobs will not be started until application startup completes.
    /// This avoids the running of jobs <em>during</em> application startup.
    /// </summary>
    public bool AwaitApplicationStarted { get; set; } = true;

private static void AddHostedService(
    IServiceCollection services,
    [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicConstructors)] Type implementationType)
{
    var existing = services.FirstOrDefault(descriptor =>
        descriptor.ServiceType == typeof(IHostedService)
        && descriptor.ImplementationType is not null
        && typeof(QuartzHostedService).IsAssignableFrom(descriptor.ImplementationType));

    if (existing is null)
    {
        services.Add(ServiceDescriptor.Singleton(typeof(IHostedService), implementationType));
        return;
    }

    if (existing.ImplementationType != implementationType
        && existing.ImplementationType == typeof(QuartzHostedService))
    {
        services.Remove(existing);
        services.Add(ServiceDescriptor.Singleton(typeof(IHostedService), implementationType));
    }
}

public MicrosoftDependencyInjectionJobFactory(
    IServiceProvider serviceProvider,
    IOptions<JobFactoryOptions>? options = null,
    ILoggerFactory? loggerFactory = null) : base(loggerFactory)
{
    this.serviceProvider = serviceProvider ?? throw new ArgumentNullException(nameof(serviceProvider));
    this.options = options?.Value ?? new JobFactoryOptions();

    // Read once rather than per fire. A factory handed the raw container - by a caller constructing
    // one itself, or because this is the default scheduler, which has no wrapper - has no key, and
    // resolves jobs exactly as it always did.
    schedulerKey = (serviceProvider as SchedulerScopedServiceProvider)?.SchedulerServiceKey;

    mayBuildWithoutScope = GetType() == typeof(MicrosoftDependencyInjectionJobFactory);
}

private (IJob Job, bool FromContainer) ResolveJob(TriggerFiredBundle bundle, IServiceProvider serviceProvider)
{
    var jobType = bundle.JobDetail.JobType.ResolvedType;

    // Before the container is asked anything: GetService constructs whatever is registered for the
    // type it is handed, and a cast afterwards is a cast on an object that already exists.
    JobType.EnsureIsJob(jobType);

    var job = schedulerKey is null ? null : (IJob?) serviceProvider.GetKeyedService(jobType, schedulerKey);
    job ??= (IJob?) serviceProvider.GetService(jobType);

    if (job is not null)
    {
        // use the registered one
        return (job, true);
    }

    return (activatorCache.CreateInstance(serviceProvider, jobType), false);
}

private ConstructorInvoker? FindUnscopedConstructor(TriggerFiredBundle bundle)
{
    // Read per firing rather than once: the options instance is shared, and a hook added to it after
    // this factory was built is one the scope path would run.
    if (!mayBuildWithoutScope || options.ConfigureScope is not null)
    {
        return null;
    }

    if (bundle.JobDetail.JobType.GetLoadedType() is not { } jobType)
    {
        return null;
    }

    // Looked up before it is decided rather than through a GetOrAdd factory, for the reason
    // JobActivatorCache gives: a lambda's parameter carries no annotation.
    if (unscopedConstructors.TryGetValue(jobType, out ConstructorInvoker? constructor))
    {
        return constructor;
    }

    return unscopedConstructors.GetOrAdd(jobType, DecideUnscopedConstructor(jobType));
}

private ConstructorInvoker? DecideUnscopedConstructor(
    [DynamicallyAccessedMembers(DynamicallyAccessedMemberTypes.PublicConstructors)] Type jobType)
{
    // Not a job, or not one anything could construct: the scope path refuses it with the message it
    // always has.
    if (!typeof(IJob).IsAssignableFrom(jobType) || jobType.IsAbstract || jobType.IsValueType || jobType.ContainsGenericParameters)
    {
        return null;
    }

    ConstructorInfo[] constructors = jobType.GetConstructors();
    if (constructors.Length != 1 || constructors[0].GetParameters().Length != 0)
    {
        return null;
    }

if (serviceProvider.GetService(typeof(IServiceProviderIsService)) is not IServiceProviderIsService registrations
    || registrations.IsService(jobType))
{
    return null;
}

if (schedulerKey is not null
    && (serviceProvider.GetService(typeof(IServiceProviderIsKeyedService)) is not IServiceProviderIsKeyedService keyedRegistrations
        || keyedRegistrations.IsKeyedService(jobType, schedulerKey)))
{
    return null;
}

return ConstructorInvoker.Create(constructors[0]);

public sealed class CronScheduleBuilder : IScheduleBuilder, IHashKeyAwareScheduleBuilder
{
    private CronExpression? cronExpression;
    private readonly string? deferredHashExpression;
    private TimeZoneInfo? deferredTimeZone;
    private int misfireInstruction = MisfireInstruction.SmartPolicy;

CronTriggerImpl ct = new CronTriggerImpl();

// CronExpression is immutable, so every trigger built here can safely share this instance;
// its setter also adopts the expression's time zone as the trigger's.
ct.CronExpression = cronExpression;
ct.MisfireInstructionCode = misfireInstruction;

return ct;

public CronScheduleBuilder WithMisfireInstruction(CronTriggerMisfireInstruction instruction)
{
    misfireInstruction = (int) instruction;
    return this;
}

public enum CronTriggerMisfireInstruction
{
    /// <summary>
    /// Let the scheduler pick the policy. This is the default, and for a cron trigger it means
    /// <see cref="FireAndProceed" />.
    /// </summary>
    /// <remarks>
    /// Spelled <c>SmartPolicy</c> in XML and JSON scheduling data.
    /// </remarks>
    SmartPolicy = MisfireInstruction.SmartPolicy,

    /// <summary>
    /// Never treat a missed firing as a misfire: fire every missed firing as soon as possible.
    /// </summary>
    /// <remarks>
    /// A trigger that missed many firings will fire that many times in rapid succession while it
    /// catches up.
    /// <para>Spelled <c>IgnoreMisfirePolicy</c> in XML and JSON scheduling data.</para>
    /// </remarks>
    IgnoreMisfires = MisfireInstruction.IgnoreMisfirePolicy,

    /// <summary>
    /// Fire once now, then resume the schedule.
    /// </summary>
    /// <remarks>
    /// Spelled <c>FireOnceNow</c> in XML and JSON scheduling data.
    /// </remarks>
    FireAndProceed = MisfireInstruction.CronTrigger.FireOnceNow,

    /// <summary>
    /// Skip the missed firings and resume at the next scheduled time.
    /// </summary>
    /// <remarks>
    /// Spelled <c>DoNothing</c> in XML and JSON scheduling data.
    /// </remarks>
    DoNothing = MisfireInstruction.CronTrigger.DoNothing,
}

public override void UpdateAfterMisfire(ICalendar? calendar)
{
    int instr = MisfireInstructionCode;

    if (instr == Quartz.MisfireInstruction.SmartPolicy)
    {
        instr = Quartz.MisfireInstruction.CronTrigger.FireOnceNow;
    }

if (instr == Quartz.MisfireInstruction.CronTrigger.DoNothing)
{
    DateTimeOffset? newFireTime = GetFireTimeAfter(TimeProvider.GetUtcNow());

    while (newFireTime.HasValue && calendar is not null
                                && !calendar.IsTimeIncluded(newFireTime.Value))
    {
        newFireTime = GetFireTimeAfter(newFireTime);

        if (!newFireTime.HasValue)
        {
            break;
        }

        //avoid infinite loop
        if (newFireTime.Value.Year > TriggerConstants.YearToGiveUpSchedulingAt)
        {
            newFireTime = null;
        }
    }
    NextFireTimeUtc = newFireTime;

public override void UpdateAfterMisfire(ICalendar? calendar)
{
    int instr = MisfireInstructionCode;

    if (instr == Quartz.MisfireInstruction.SmartPolicy)
    {
        instr = Quartz.MisfireInstruction.CronTrigger.FireOnceNow;
    }

    if (instr == Quartz.MisfireInstruction.CronTrigger.DoNothing)
    {
        DateTimeOffset? newFireTime = GetFireTimeAfter(TimeProvider.GetUtcNow());

        while (newFireTime.HasValue && calendar is not null
                                    && !calendar.IsTimeIncluded(newFireTime.Value))
        {
            newFireTime = GetFireTimeAfter(newFireTime);

            if (!newFireTime.HasValue)
            {
                break;
            }

            //avoid infinite loop
            if (newFireTime.Value.Year > TriggerConstants.YearToGiveUpSchedulingAt)
            {
                newFireTime = null;
            }
        }
        NextFireTimeUtc = newFireTime;
    }
    else if (instr == Quartz.MisfireInstruction.CronTrigger.FireOnceNow)
    {
        NextFireTimeUtc = TimeProvider.GetUtcNow();
    }
}

private async ValueTask CreateSchedulers(CancellationToken cancellationToken)
{
    var factory = serviceProvider.GetService<ISchedulerFactory>();
    if (factory is not null)
    {
        var scheduler = await factory.GetScheduler(cancellationToken).ConfigureAwait(false);
        schedulers.Add(new HostedScheduler(scheduler, options.Get(Options.DefaultName)));
    }

    var registry = serviceProvider.GetService<SchedulerNameRegistry>();
    foreach (var name in registry?.Names ?? [])
    {
        // Each named scheduler's factory is registered under the scheduler's name as the service key.
        var named = serviceProvider.GetRequiredKeyedService<ISchedulerFactory>(name);
        var scheduler = await named.GetScheduler(cancellationToken).ConfigureAwait(false);
        schedulers.Add(new HostedScheduler(scheduler, options.Get(name)));
    }

    if (schedulers.Count == 0)
    {
        Throw.SchedulerConfigException(
            "AddQuartzHostedService() was called but no scheduler is registered in the container, so "
            + "there is nothing to start. Call AddQuartz(...) to register one.");
    }
}

public async Task StartAsync(CancellationToken cancellationToken)
{
    try
    {
        // Require successful initialization for application startup to succeed
        await CreateSchedulers(cancellationToken).ConfigureAwait(false);

        // Sensible mode: proceed with startup, and have jobs start after application startup.
        // Follow the pattern from BackgroundService.StartAsync: https://github.com/dotnet/runtime/blob/main/src/libraries/Microsoft.Extensions.Hosting.Abstractions/src/BackgroundService.cs
        // A scheduler the application starts itself is not waited for: it is nothing this service
        // will start once startup completes, so it must not be what keeps a startup task alive.
        if (schedulers.Exists(static scheduler => scheduler.Options is { AutoStart: true, AwaitApplicationStarted: true }))
        {
            startupTask = AwaitStartupCompletionAndStartSchedulers(cancellationToken);

            // If the task completed synchronously, await it in order to bubble potential cancellation/failure to the caller
            // Otherwise, return, allowing application startup to complete
            if (startupTask.IsCompleted)
            {
                await startupTask.ConfigureAwait(false);
            }
        }
        else // Legacy mode: start jobs inline
        {
            startupTask = StartSchedulers(waitForApplicationStarted: false, cancellationToken);
            await startupTask.ConfigureAwait(false);
        }

private async Task AwaitStartupCompletionAndStartSchedulers(CancellationToken startupCancellationToken)
{
    // The schedulers that were told not to wait start before anything is awaited.
    await StartSchedulers(waitForApplicationStarted: false, startupCancellationToken).ConfigureAwait(false);

    using var combinedCancellationSource = CancellationTokenSource.CreateLinkedTokenSource(startupCancellationToken, applicationLifetime.ApplicationStarted);

    await Task.Delay(Timeout.InfiniteTimeSpan, combinedCancellationSource.Token) // Wait "indefinitely", until startup completes or is aborted
        .ContinueWith(_ => { }, CancellationToken.None, TaskContinuationOptions.OnlyOnCanceled, TaskScheduler.Default) // Without an OperationCanceledException on cancellation
        .ConfigureAwait(false);

    if (!startupCancellationToken.IsCancellationRequested)
    {
        // Startup has finished, but ApplicationStopping may still interrupt starting of the scheduler
        await StartSchedulers(waitForApplicationStarted: true, applicationLifetime.ApplicationStopping).ConfigureAwait(false);
    }
}

private async ValueTask CreateSchedulers(CancellationToken cancellationToken)
{
    var factory = serviceProvider.GetService<ISchedulerFactory>();
    if (factory is not null)
    {
        var scheduler = await factory.GetScheduler(cancellationToken).ConfigureAwait(false);
        schedulers.Add(new HostedScheduler(scheduler, options.Get(Options.DefaultName)));
    }

    var registry = serviceProvider.GetService<SchedulerNameRegistry>();
    foreach (var name in registry?.Names ?? [])
    {
        // Each named scheduler's factory is registered under the scheduler's name as the service key.
        var named = serviceProvider.GetRequiredKeyedService<ISchedulerFactory>(name);
        var scheduler = await named.GetScheduler(cancellationToken).ConfigureAwait(false);
        schedulers.Add(new HostedScheduler(scheduler, options.Get(name)));
    }

private async Task StartSchedulers(bool waitForApplicationStarted, CancellationToken cancellationToken)
{
    // Avoid potential race conditions between ourselves and StopAsync, in case it has already made its attempt to stop the scheduler
    if (applicationLifetime.ApplicationStopping.IsCancellationRequested)
    {
        return;
    }

    foreach (var hosted in schedulers)
    {
        // Tested before the two settings that say *when* to start, because AutoStart says whether
        // to at all: the scheduler was created and bound by CreateSchedulers, and that is all this
        // service does for it. The application presses start.
        if (!hosted.Options.AutoStart)
        {
            continue;
        }

        if (hosted.Options.AwaitApplicationStarted != waitForApplicationStarted)
        {
            continue;
        }

        if (hosted.Options.StartDelay.HasValue)
        {
            await hosted.Scheduler.StartDelayed(hosted.Options.StartDelay.Value, cancellationToken).ConfigureAwait(false);
        }
        else
        {
            await hosted.Scheduler.Start(cancellationToken).ConfigureAwait(false);
        }
    }
}

public async Task StartAsync(CancellationToken cancellationToken)
{
    try
    {
        // Require successful initialization for application startup to succeed
        await CreateSchedulers(cancellationToken).ConfigureAwait(false);

        // Sensible mode: proceed with startup, and have jobs start after application startup.
        // Follow the pattern from BackgroundService.StartAsync: https://github.com/dotnet/runtime/blob/main/src/libraries/Microsoft.Extensions.Hosting.Abstractions/src/BackgroundService.cs
        // A scheduler the application starts itself is not waited for: it is nothing this service
        // will start once startup completes, so it must not be what keeps a startup task alive.
        if (schedulers.Exists(static scheduler => scheduler.Options is { AutoStart: true, AwaitApplicationStarted: true }))
        {
            startupTask = AwaitStartupCompletionAndStartSchedulers(cancellationToken);

            // If the task completed synchronously, await it in order to bubble potential cancellation/failure to the caller
            // Otherwise, return, allowing application startup to complete
            if (startupTask.IsCompleted)
            {
                await startupTask.ConfigureAwait(false);
            }
        }
        else // Legacy mode: start jobs inline
        {
            startupTask = StartSchedulers(waitForApplicationStarted: false, cancellationToken);
            await startupTask.ConfigureAwait(false);
        }
    }
    catch (OperationCanceledException)
    {
        // if the operation was canceled, we should not start the scheduler
    }
    catch (Exception)
    {
        // A scheduler created before the failure is already bound to the repository, so it has to be
        // shut down rather than left behind by a host that will never call StopAsync.
        await ShutdownSchedulers(CancellationToken.None).ConfigureAwait(false);
        throw;
    }

public Task StopAsync(CancellationToken cancellationToken)
{
    Task stop;
    lock (stopGate)
    {
        // The second caller's token is deliberately ignored: there is one stop, it runs under the
        // token of whichever call started it, and a later call waits for that rather than starting
        // a second shutdown of schedulers the first one is already tearing down.
        stop = stopTask ??= StopCore(cancellationToken);
    }

    return stop;
}

private async Task StopCore(CancellationToken cancellationToken)
{
    // Stopped without having been started
    if (Volatile.Read(ref schedulers).Count == 0)
    {
        return;
    }

    try
    {
        // Wait until any ongoing startup logic has finished or the graceful shutdown period is over
        if (startupTask is not null)
        {
            await Task.WhenAny(startupTask, Task.Delay(Timeout.Infinite, cancellationToken)).ConfigureAwait(false);
        }
    }
    finally
    {
        // we always need to call shutdown to ensure that we unbind the scheduler from global repository
        await ShutdownSchedulers(cancellationToken).ConfigureAwait(false);
    }
}

private async ValueTask ShutdownSchedulers(CancellationToken cancellationToken)
{
    List<HostedScheduler> toShutDown = Interlocked.Exchange(ref schedulers, []);

    // Each under its own name, so AddQuartzHostedService("acme", o => o.WaitForJobsToComplete = true)
    // configures a tenant that did not exist when that line was written.
    foreach (IScheduler tenant in serviceProvider.GetService<SchedulerRuntime>()?.TakeLiveSchedulers() ?? [])
    {
        toShutDown.Add(new HostedScheduler(tenant, options.Get(tenant.SchedulerName)));
    }

private async ValueTask ShutdownSchedulers(CancellationToken cancellationToken)
{
    List<HostedScheduler> toShutDown = Interlocked.Exchange(ref schedulers, []);

    // Each under its own name, so AddQuartzHostedService("acme", o => o.WaitForJobsToComplete = true)
    // configures a tenant that did not exist when that line was written.
    foreach (IScheduler tenant in serviceProvider.GetService<SchedulerRuntime>()?.TakeLiveSchedulers() ?? [])
    {
        toShutDown.Add(new HostedScheduler(tenant, options.Get(tenant.SchedulerName)));
    }

    // Every shutdown is started before any of them is awaited, so that the waits for running jobs
    // overlap. A scheduler that throws before it yields is captured rather than left to abandon the
    // schedulers after it in the list.
    List<Task> shutdowns = new List<Task>(toShutDown.Count);
    foreach (HostedScheduler hosted in toShutDown)
    {
        try
        {
            shutdowns.Add(hosted.Scheduler.Shutdown(hosted.Options.WaitForJobsToComplete, cancellationToken).AsTask());
        }
        catch (Exception e)
        {
            shutdowns.Add(Task.FromException(e));
        }
    }

// Every shutdown is started before any of them is awaited, so that the waits for running jobs
// overlap. A scheduler that throws before it yields is captured rather than left to abandon the
// schedulers after it in the list.
List<Task> shutdowns = new List<Task>(toShutDown.Count);
foreach (HostedScheduler hosted in toShutDown)
{
    try
    {
        shutdowns.Add(hosted.Scheduler.Shutdown(hosted.Options.WaitForJobsToComplete, cancellationToken).AsTask());
    }
    catch (Exception e)
    {
        shutdowns.Add(Task.FromException(e));
    }
}

List<Exception>? exceptions = null;
foreach (Task shutdown in shutdowns)
{
    try
    {
        await shutdown.ConfigureAwait(false);
    }
    catch (Exception e)
    {
        exceptions ??= [];
        exceptions.Add(e);
    }
}

if (exceptions is { Count: > 0 })
{
    throw new AggregateException("One or more scheduler shutdowns failed.", exceptions);
}

