public async ValueTask DisposeAsync()
{
    // A derived factory may dispose this as well as leaving it to us, and a scope closed
    // twice throws from the container rather than from anything we control.
    if (Interlocked.Exchange(ref disposed, 1) != 0)
    {
        return;
    }

    try
    {
        // Only a job we activated ourselves; one the container produced is registered with
        // the scope and disposed by it below.
        if (disposeJob)
        {
            await DisposeIfDisposable(job).ConfigureAwait(false);
        }
    }
    finally
    {
        await DisposeScope(scope).ConfigureAwait(false);
    }
}

var scope = serviceProvider.CreateScope();

try
{
    ConfigureScope(scope, bundle, scheduler);
    var (job, fromContainer) = ResolveJob(bundle, scope.ServiceProvider);

    // The scope rides along as the job's state so that ReturnJob can tear it down. The job
    // itself is handed to the scheduler unwrapped, so listeners and the execution context see
    // the type the user wrote rather than something of ours standing in front of it.
    return new ValueTask<JobScope>(new JobScope(job, new ScopeState(scope, job, disposeJob: !fromContainer)));
}
catch (Exception e)
{
    // ReturnJob is not called when CreateJob throws, so the scope we just opened would be
    // abandoned - along with every scoped dependency already resolved into it.
    return DisposeScopeAndRethrow(scope, e);
}

static async ValueTask<JobScope> DisposeScopeAndRethrow(IServiceScope scope, Exception failure)
{
    await DisposeScope(scope).ConfigureAwait(false);
    ExceptionDispatchInfo.Capture(failure).Throw();
    return default;
}

public override ValueTask<JobScope> CreateJob(TriggerFiredBundle bundle, IScheduler scheduler, CancellationToken cancellationToken = default)
{
    var creatingScope = CreateJobInstance(bundle, scheduler, cancellationToken);

    if (!creatingScope.IsCompletedSuccessfully)
    {
        return AwaitScope(this, creatingScope, bundle, scheduler, cancellationToken);
    }

    var scope = creatingScope.Result;

    try
    {
        ApplyProperties(scope, bundle, scheduler);
    }
    catch (Exception e)
    {
        // The job exists by now, and whatever the factory allocated to produce it is in the
        // scope's state. ReturnJob is not called when CreateJob throws, so hand it back here
        // rather than leaking it on every fire of a job whose data map does not match.
        return ReturnAndRethrow(this, scope, e, cancellationToken);
    }

    return new ValueTask<JobScope>(scope);

    static async ValueTask<JobScope> AwaitScope(
        PropertySettingJobFactory factory,
        ValueTask<JobScope> creatingScope,
        TriggerFiredBundle bundle,
        IScheduler scheduler,
        CancellationToken cancellationToken)
    {
        var scope = await creatingScope.ConfigureAwait(false);

        try
        {
            factory.ApplyProperties(scope, bundle, scheduler);
        }
        catch (Exception e)
        {
            return await ReturnAndRethrow(factory, scope, e, cancellationToken).ConfigureAwait(false);
        }

        return scope;
    }

    static async ValueTask<JobScope> ReturnAndRethrow(
        PropertySettingJobFactory factory,
        JobScope scope,
        Exception failure,
        CancellationToken cancellationToken)
    {
        try
        {
            await factory.ReturnJob(scope, cancellationToken).ConfigureAwait(false);
        }
        catch (Exception e)
        {
            // Never let cleanup replace the failure that caused it.
            factory.logger.JobReturnAfterFailedCreationFailed(e);
        }

        ExceptionDispatchInfo.Capture(failure).Throw();
        return default;
    }

if (FindUnscopedConstructor(bundle) is { } constructor)
{
